import { cleanupOutdatedCaches, precacheAndRoute } from 'workbox-precaching';
import { version as twemojiVersion } from '@twemoji/svg/package.json';
import { version as dataVersion } from '@emoji-mart/data/package.json';
import { CATEGORY_SHEETS, sheetKey, sheetPath } from './emoji/emojiSheets';
import { notificationFromPush } from './services/pushNotifications';
import { isMediaRequest, handleMediaFetch, MEDIA_PING } from './services/mediaStreamWorker';

// Inject manifest generated by VitePWA
precacheAndRoute(self.__WB_MANIFEST);
cleanupOutdatedCaches();

// A new version installs alongside the old one and waits; the app shows an Update button,
// which sends this (workbox-window's messageSkipWaiting) to switch over.
self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
  // The page checks this worker can stream encrypted videos (an older one can't), and save
  // files (since 2026-10-08; older ones answered `true`).
  if (event.data?.type === MEDIA_PING) event.ports[0]?.postMessage({ stream: true, download: true });
});

// Encrypted videos, streamed and seeked a piece at a time, and files saved without the page
// holding them (services/mediaStreamWorker.js).
self.addEventListener('fetch', (event) => {
  if (isMediaRequest(event.request)) handleMediaFetch(event);
});

// Emoji images (/emoji/<codepoints>.svg and the picker's sprite sheets,
// /emoji/sheets/<key>/<name>.webp, see vite.config.js): cache-first, kept per Twemoji
// version. Once an emoji has been shown it never touches the network again, so the picker and
// messages draw instantly on later visits, without any server-side cache configuration.
const EMOJI_CACHE = `emoji-${twemojiVersion}`;
const EMOJI_PATH = /\/emoji\/([0-9a-f-]+\.svg|sheets\/[^/]+\/[a-z0-9]+\.webp)$/;
const SHEET_KEY = sheetKey(twemojiVersion, dataVersion);
const emojiPath = (file) => new URL(`emoji/${file}`, self.registration.scope).pathname;
// Fetched as soon as this worker installs, so even the first picker opened shows at once:
// the default-tone sheets, and the message action sheet's default quick reactions
// (emoji/quickReactions.js: 👍 ❤️ 😂 😮 😢 🙏).
const EMOJI_WARM = [
  ...CATEGORY_SHEETS.map((name) => sheetPath(SHEET_KEY, name)),
  ...['1f44d', '2764', '1f602', '1f62e', '1f622', '1f64f'].map((file) => `${file}.svg`),
].map(emojiPath);

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(EMOJI_CACHE);
      await Promise.all(EMOJI_WARM.map(async (path) => {
        if (await cache.match(path)) return;
        const response = await fetch(path);
        if (response.ok) await cache.put(path, response);
      }));
    } catch {
      // Offline or the like: they're fetched when first shown instead.
    }
  })());
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== self.location.origin || !EMOJI_PATH.test(url.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(EMOJI_CACHE);
    const cached = await cache.match(url.pathname);
    if (cached) return cached;
    const response = await fetch(event.request);
    if (response.ok) event.waitUntil(cache.put(url.pathname, response.clone()));
    return response;
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((n) => n.startsWith('emoji-') && n !== EMOJI_CACHE).map((n) => caches.delete(n)));
    // Sprite sheets of an older layout (a new emoji data version or LAYOUT_VERSION).
    const cache = await caches.open(EMOJI_CACHE);
    const current = emojiPath(`sheets/${SHEET_KEY}/`);
    const stale = (await cache.keys()).filter((request) => {
      const { pathname } = new URL(request.url);
      return pathname.includes('/emoji/sheets/') && !pathname.startsWith(current);
    });
    await Promise.all(stale.map((request) => cache.delete(request)));
  })());
});

// Pushes about new messages (server/push.js MESSAGE_PUSHES).
const MESSAGE_PUSHES = new Set(['dm', 'group', 'guild', 'bot_dm']);

self.addEventListener('push', (event) => {
  event.waitUntil((async () => {
    let data;
    try {
      data = event.data.json();
    } catch {
      data = { title: 'Voicaw', body: event.data?.text() };
    }

    // Every push must show a notification (browsers, Safari especially, revoke push for
    // sites that don't). The server skips pushes for a chat the user is looking at.
    // (Only reactions in encrypted chats can come back empty, and the server never web-pushes
    // those; should one arrive anyway, something must still be shown.)
    const { title, options } = await notificationFromPush(data) ?? await notificationFromPush({ title: data.title });
    // When one of the app's pages plays its own Message sound for it (sounds/sounds.js), the
    // notification itself stays quiet.
    if (MESSAGE_PUSHES.has(data.type) && await aPagePlaysMessageSound()) options.silent = true;
    await self.registration.showNotification(title, options);
  })());
});

// Asks each open page whether it plays the Message sound (sounds.js handlesMessageSound). A
// page that doesn't answer in time (frozen, or an older version) counts as no, unless it's
// focused: a page in front has always played it.
const SOUND_ANSWER_MS = 500;

async function aPagePlaysMessageSound() {
  const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  if (windows.some((client) => client.focused)) return true;
  const answers = windows.map((client) => new Promise((resolve) => {
    const channel = new MessageChannel();
    channel.port1.onmessage = (event) => resolve(event.data === true);
    setTimeout(() => resolve(false), SOUND_ANSWER_MS);
    client.postMessage({ action: 'handles-message-sound' }, [channel.port2]);
  }));
  return (await Promise.all(answers)).some(Boolean);
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = new URL(event.notification.data?.url || '/', self.location.origin).href;

  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const existing = windows.find((c) => c.url.startsWith(self.registration.scope) && 'focus' in c);
    if (existing) {
      await existing.focus();
      // The app navigates itself (SWMessageHandler in App.jsx) to keep its state.
      existing.postMessage({ action: 'navigate', url: new URL(targetUrl).pathname });
      return;
    }
    await self.clients.openWindow(targetUrl);
  })());
});

// The push service replaced our subscription (e.g. it expired). Subscribe again and tell
// the server, identifying the device by its old endpoint (we have no login token here).
// If this can't complete, the app re-syncs the subscription the next time it's opened.
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil((async () => {
    const oldEndpoint = event.oldSubscription?.endpoint;
    const options = event.oldSubscription?.options;
    const subscription = event.newSubscription ||
      (options?.applicationServerKey && await self.registration.pushManager.subscribe(options));
    if (!oldEndpoint || !subscription) return;

    await fetch(`${import.meta.env.VITE_API_BASE_URL}update-subscription`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ oldEndpoint, subscription: subscription.toJSON() }),
    });
  })());
});
